    "go": "package main\n\nimport (\n\t\"context\"\n\t\"encoding/json\"\n\t\"net/http\"\n)\n\n// Repository Layer Interface (Data Persistence Abstraction)\ntype UserRepository interface {\n\tFindByID(ctx context.Context, id int64) (*User, error)\n}\n\n// Service Layer (Pure Business Logic - Transport Agnostic)\ntype UserService struct {\n\trepo UserRepository\n}\n\nfunc (s *UserService) GetUserProfile(ctx context.Context, id int64) (*User, error) {\n\t// Enforce domain invariant: system users are restricted\n\tif id <= 0 {\n\t\treturn nil, ErrInvalidUserID\n\t}\n\treturn s.repo.FindByID(ctx, id)\n}\n\n// Controller / Handler Layer (HTTP Transport Only)\ntype UserHandler struct {\n\tservice *UserService\n}\n\nfunc (h *UserHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {\n\tuser, err := h.service.GetUserProfile(r.Context(), 42)\n\tif err != nil {\n\t\thttp.Error(w, err.Error(), http.StatusBadRequest)\n\t\treturn\n\t}\n\tw.Header().Set(\"Content-Type\", \"application/json\")\n\tw.WriteHeader(http.StatusOK)\n\t_ = json.NewEncoder(w).Encode(user)\n}",
    "typescript": "// Clean Architecture / Layered Pattern in TypeScript\nexport interface UserRepository {\n  findById(id: string): Promise<User | null>;\n}\n\n// Pure Domain Service (Zero knowledge of HTTP / req / res)\nexport class UserService {\n  constructor(private readonly userRepo: UserRepository) {}\n\n  async getUserProfile(userId: string): Promise<User> {\n    if (!userId || userId.length < 5) {\n      throw new DomainValidationError(\"Invalid user ID format\");\n    }\n    const user = await this.userRepo.findById(userId);\n    if (!user) throw new EntityNotFoundError(\"User not found\");\n    return user;\n  }\n}\n\n// HTTP Controller Layer (Transport Only)\nexport class UserController {\n  constructor(private readonly userService: UserService) {}\n\n  async handleGet(req: Request, res: Response) {\n    try {\n      const user = await this.userService.getUserProfile(req.params.id);\n      return res.status(200).json({ data: user });\n    } catch (err: any) {\n      return res.status(err.statusCode || 500).json({ error: err.message });\n    }\n  }\n}",
    "python": "from abc import ABC, abstractmethod\nfrom typing import Optional\nfrom dataclasses import dataclass\nfrom fastapi import APIRouter, Depends, HTTPException, status\n\n@dataclass\nclass User:\n    id: int\n    email: str\n\n# Repository Interface (Dependency Inversion)\nclass UserRepository(ABC):\n    @abstractmethod\n    async def find_by_id(self, user_id: int) -> Optional[User]:\n        pass\n\n# Service Layer (Pure Domain Logic)\nclass UserService:\n    def __init__(self, repo: UserRepository):\n        self._repo = repo\n\n    async def get_user_profile(self, user_id: int) -> User:\n        if user_id <= 0:\n            raise ValueError(\"User ID must be positive\")\n        user = await self._repo.find_by_id(user_id)\n        if not user:\n            raise KeyError(\"User not found\")\n        return user\n\n# Transport Controller (FastAPI Router)\nrouter = APIRouter(prefix=\"/users\")\n\n@router.get(\"/{user_id}\")\nasync def get_user(user_id: int, service: UserService = Depends(get_user_service)):\n    try:\n        user = await service.get_user_profile(user_id)\n        return {\"data\": user}\n    except ValueError as e:\n        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=str(e))\n    except KeyError:\n        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail=\"User not found\")"
