    "go": "package main\n\nimport (\n\t\"bufio\"\n\t\"fmt\"\n\t\"net\"\n\t\"strings\"\n)\n\n// Raw TCP Socket Server handling HTTP/1.1 frame manually\nfunc main() {\n\tlistener, err := net.Listen(\"tcp\", \":8080\")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer listener.Close()\n\n\tfor {\n\t\tconn, err := listener.Accept()\n\t\tif err != nil {\n\t\t\tcontinue\n\t\t}\n\t\tgo handleConnection(conn)\n\t}\n}\n\nfunc handleConnection(conn net.Conn) {\n\tdefer conn.Close()\n\treader := bufio.NewReader(conn)\n\n\t// Parse Request-Line: GET /api/v1/health HTTP/1.1\n\tline, err := reader.ReadString('\\n')\n\tif err != nil {\n\t\treturn\n\t}\n\tparts := strings.Fields(line)\n\tif len(parts) < 3 {\n\t\treturn\n\t}\n\n\tbody := \"{\\\"status\\\":\\\"healthy\\\"}\"\n\tresp := fmt.Sprintf(\"HTTP/1.1 200 OK\\r\\nContent-Type: application/json\\r\\nContent-Length: %d\\r\\nConnection: close\\r\\n\\r\\n%s\", len(body), body)\n\tconn.Write([]byte(resp))\n}",
    "typescript": "import net from \"net\";\n\n// Raw TCP Socket Server parsing HTTP frame in Node.js\nconst server = net.createServer((socket) => {\n  socket.on(\"data\", (buffer) => {\n    const request = buffer.toString(\"utf-8\");\n    const [requestLine] = request.split(\"\\r\\n\");\n    const [method, path, protocol] = requestLine.split(\" \");\n\n    console.log(`Received ${method} request on ${path} using ${protocol}`);\n\n    const payload = JSON.stringify({ status: \"healthy\", timestamp: Date.now() });\n    const response = [\n      \"HTTP/1.1 200 OK\",\n      \"Content-Type: application/json\",\n      `Content-Length: ${Buffer.byteLength(payload)}`,\n      \"Connection: close\",\n      \"\",\n      payload\n    ].join(\"\\r\\n\");\n\n    socket.write(response);\n    socket.end();\n  });\n});\n\nserver.listen(8080, () => console.log(\"TCP HTTP Listener active on :8080\"));",
    "python": "import socket\n\n# Low-level TCP socket server accepting HTTP frames\nserver_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)\nserver_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)\nserver_socket.bind((\"0.0.0.0\", 8080))\nserver_socket.listen(128)\n\nprint(\"Listening on port 8080...\")\nwhile True:\n    client_conn, client_addr = server_socket.accept()\n    with client_conn:\n        raw_data = client_conn.recv(4096).decode(\"utf-8\")\n        request_line = raw_data.split(\"\\r\\n\")[0]\n        method, path, _ = request_line.split(\" \")\n\n        body = '{\"status\":\"healthy\",\"engine\":\"raw-socket\"}'\n        response = (\n            \"HTTP/1.1 200 OK\\r\\n\"\n            \"Content-Type: application/json\\r\\n\"\n            f\"Content-Length: {len(body)}\\r\\n\"\n            \"Connection: close\\r\\n\\r\\n\"\n            f\"{body}\"\n        )\n        client_conn.sendall(response.encode(\"utf-8\"))"
