    "go": "// Preserving 64-bit Int Precision with Protobuf / Safe JSON\ntype Transaction struct {\n\tID        int64  `json:\"id,string\" protobuf:\"varint,1,opt,name=id\"` // Serialize as string in JSON\n\tAccountID int64  `json:\"account_id,string\" protobuf:\"varint,2,opt,name=account_id\"`\n\tAmount    int64  `json:\"amount\" protobuf:\"varint,3,opt,name=amount\"`\n}\n\nfunc MarshalTransaction(t *Transaction) ([]byte, error) {\n\t// JSON marshaling with string tag prevents JavaScript 2^53-1 precision truncation\n\treturn json.Marshal(t)\n}",
    "typescript": "// BigInt Safe JSON Serialization (Preserving 64-bit Integers)\nexport function safeJSONStringify(obj: any): string {\n  return JSON.stringify(obj, (key, value) => {\n    // Convert 64-bit BigInts to strings so frontend does not lose precision\n    if (typeof value === \"bigint\") {\n      return value.toString();\n    }\n    return value;\n  });\n}\n\nexport function safeJSONParse(text: string): any {\n  return JSON.parse(text, (key, value) => {\n    // Rehydrate stringified large numeric IDs into BigInt\n    if (typeof value === \"string\" && /^[0-9]{16,}$/.test(value)) {\n      return BigInt(value);\n    }\n    return value;\n  });\n}",
