    "typescript": "// Pure Service with Dependency Injection\nexport class OrderService {\n  constructor(\n    private readonly repo: OrderRepository,\n    private readonly paymentGateway: PaymentGateway\n  ) {}\n\n  async checkout(userId: string, amountCents: number) {\n    // Pure business domain rules (no req, res, status codes)\n    if (amountCents <= 0) throw new Error(\"Invalid order amount\");\n    const charge = await this.paymentGateway.charge(userId, amountCents);\n    return await this.repo.saveOrder(userId, amountCents, charge.id);\n  }\n}",
